object.script:
function onTick() currentX = input.getNumber(1) limitX = property.getNumber("Max/Min Limit for Pitch, turn") currentY = input.getNumber(3) limitY = property.getNumber("Max/Min Limit for Yaw, turn")
limitedX = math.max(-limitX, math.min(limitX, currentX)) limitedY = math.max(-limitY, math.min(limitY, currentY))
output.setNumber(1, limitedX) output.setNumber(2, limitedY) end
